  });

  it("writes snapshot rows in chunks", async () => {
    const userCount = 1200;
    const userIds = Array.from({ length: userCount }).map((_, i) => `u_${i}`);

    const groupBy = vi
      .fn()
      .mockResolvedValueOnce(
