}

function addSeatedPlayer(state: PokerState, userId: string, seat: number): void {
  const player = new PlayerState();
  player.id = userId;
  player.userId = userId;
  player.seat = seat;
  player.status = "ACTIVE";
  state.playersById.set(userId, player);
  state.seats[seat] = userId;
}

