import { describe, expect, it, vi } from "vitest";
import { SettlementService } from "./SettlementService.js";
import { PokerState } from "../../../state/PokerState.js";
import { PlayerState } from "../../../state/PlayerState.js";

function makePlayer(input: {
  id: string;
  seat: number;
  stackCents: number;
  roundBetCents?: number;
  committedCents?: number;
  status?: PlayerState["status"];
  needsAction?: boolean;
}): PlayerState {
  const player = new PlayerState();
  player.id = input.id;
  player.userId = input.id;
  player.name = input.id;
  player.seat = input.seat;
  player.kind = "HUMAN";
  player.stackCents = input.stackCents;
  player.roundBetCents = input.roundBetCents ?? 0;
  player.committedCents = input.committedCents ?? 0;
  player.status = input.status ?? "ACTIVE";
  player.needsAction = input.needsAction ?? true;
  return player;
}

function makeService() {
  const state = new PokerState();
  state.tableId = "table_settlement";
  state.handId = "hand_settlement";
  state.street = "TURN";

  const recordPayout = vi.fn().mockResolvedValue(undefined);
  const persistence = {
    enabled: true,
    handHistory: {
      recordPayout,
      recordAction: vi.fn(),
      startHand: vi.fn(),
      endHand: vi.fn(),
    },
    debitBet: vi.fn().mockImplementation(async (args: { currentBalance: number; amountCents: number }) => {
      return args.currentBalance - args.amountCents;
    }),
    postBlind: vi.fn(),
    creditPayout: vi.fn().mockImplementation(async (args: { currentBalance: number; amountCents: number }) => {
      return args.currentBalance + args.amountCents;
    }),
    assertHandBalanced: vi.fn(),
  } as any;

  const service = new SettlementService({
    state,
    persistence,
    getHoleCardsByPlayerId: () => new Map<string, string[]>(),
    getHandStartingStacksByPlayerId: () => new Map<string, number>(),
  });
  return { service, state, persistence, recordPayout };
}

describe("SettlementService money safety", () => {
  it("applies debit without creating or destroying chips", async () => {
    const { service, state } = makeService();
    const player = makePlayer({
      id: "u1",
      seat: 0,
      stackCents: 1000,
      roundBetCents: 100,
      committedCents: 100,
    });
    state.playersById.set(player.id, player);
    state.potCents = 400;

    const preTotal = player.stackCents + state.potCents;

    await service.applyActionDebit(player, 250, "CALL");

    expect(player.stackCents).toBe(750);
    expect(player.roundBetCents).toBe(350);
    expect(player.committedCents).toBe(350);
    expect(state.potCents).toBe(650);
    expect(state.actionCount).toBe(1);

    const postTotal = player.stackCents + state.potCents;
    expect(postTotal).toBe(preTotal);
  });

  it("marks player ALL_IN and clears needsAction when debit reaches zero", async () => {
    const { service, state } = makeService();
    const player = makePlayer({ id: "u1", seat: 0, stackCents: 300, needsAction: true });
    state.playersById.set(player.id, player);
    state.potCents = 100;

    await service.applyActionDebit(player, 300, "ALL_IN");

    expect(player.stackCents).toBe(0);
    expect(player.status).toBe("ALL_IN");
    expect(player.needsAction).toBe(false);
    expect(state.potCents).toBe(400);
  });

  it("rejects unaffordable debits", () => {
    const { service } = makeService();
    const player = makePlayer({ id: "u1", seat: 0, stackCents: 99 });

    expect(() => service.assertCanAfford(player, 100)).toThrow("Insufficient stack");
  });

  it("fails closed when persistence returns a mismatched debit balance", async () => {
    const { service, state, persistence } = makeService();
    const player = makePlayer({ id: "u1", seat: 0, stackCents: 500, needsAction: true });
    state.playersById.set(player.id, player);
    state.potCents = 0;

    persistence.debitBet.mockResolvedValueOnce(499);

    await expect(service.applyActionDebit(player, 200, "BET")).rejects.toThrow("LEDGER_BALANCE_MISMATCH");
    expect(player.stackCents).toBe(300);
    expect(player.roundBetCents).toBe(200);
    expect(state.potCents).toBe(200);
  });

  it("fails closed when persistence returns a mismatched blind balance", async () => {
    const { service, state, persistence } = makeService();
    const player = makePlayer({ id: "u1", seat: 0, stackCents: 500, needsAction: true });
    state.playersById.set(player.id, player);

    persistence.postBlind.mockResolvedValueOnce(450);

    await expect(service.postBlind(player, "SB", 100)).rejects.toThrow("LEDGER_BALANCE_MISMATCH");
    expect(player.stackCents).toBe(400);
    expect(player.roundBetCents).toBe(100);
    expect(state.potCents).toBe(100);
  });

  it("credits payouts exactly as distributed with no phantom payout chips", async () => {
    const { service, state, persistence, recordPayout } = makeService();
    const a = makePlayer({ id: "A", seat: 0, stackCents: 1200 });
    const b = makePlayer({ id: "B", seat: 1, stackCents: 800 });
    state.playersById.set(a.id, a);
    state.playersById.set(b.id, b);

    const payouts = new Map<string, number>([
      ["A", 350],
      ["B", 250],
    ]);

    const preStacks = new Map<string, number>([
      ["A", a.stackCents],
      ["B", b.stackCents],
    ]);

    await service.creditPayoutToPlayer(a, payouts.get("A") ?? 0);
    await service.creditPayoutToPlayer(b, payouts.get("B") ?? 0);

    const actualDeltaA = a.stackCents - (preStacks.get("A") ?? 0);
    const actualDeltaB = b.stackCents - (preStacks.get("B") ?? 0);
    const plannedTotal = [...payouts.values()].reduce((sum, amount) => sum + amount, 0);
    const actualTotal = actualDeltaA + actualDeltaB;

    expect(actualDeltaA).toBe(350);
    expect(actualDeltaB).toBe(250);
    expect(actualTotal).toBe(plannedTotal);

    expect(recordPayout).toHaveBeenNthCalledWith(
      1,
      expect.objectContaining({ playerId: "A", payoutIndex: 1, amountCents: 350 }),
    );
    expect(recordPayout).toHaveBeenNthCalledWith(
      2,
      expect.objectContaining({ playerId: "B", payoutIndex: 2, amountCents: 250 }),
    );

    expect(persistence.creditPayout).toHaveBeenCalledTimes(2);
  });
});

import { getPrisma } from "@poker-champ/db";
import { nanoid } from "nanoid";

export const TABLE_NAME_REQUIRED = "TABLE_NAME_REQUIRED" as const;

export class CashierService {
  private static assertTableMeta(tableMeta: { name: string; creatorId?: string }): void {
    if (!tableMeta.name || tableMeta.name.trim().length === 0) {
      throw new Error(TABLE_NAME_REQUIRED);
    }
  }

  private static async ensureTableExists(
    tx: any,
    tableId: string,
    tableMeta: { name: string; creatorId?: string },
  ) {
    CashierService.assertTableMeta(tableMeta);
    await tx.pokerTable.upsert({
      where: { id: tableId },
      create: {
        id: tableId,
        name: tableMeta.name,
        creatorId: tableMeta.creatorId,
      },
      update: {},
    });
  }

  /**
   * Cash Game Buy-In
   * Atomically debits User.bankrollCents and credits PlayerBalance.
   */
  static async processCashGameBuyIn(params: {
    userId: string;
    tableId: string;
    amountCents: number;
    externalRef: string;
    tableMeta: { name: string; creatorId?: string };
  }): Promise<{ success: boolean; newTableBalance: number }> {
    const prisma = getPrisma();
    const { userId, tableId, amountCents, externalRef, tableMeta } = params;

    return await prisma.$transaction(async (tx: any) => {
      // Ensure FK target exists for PlayerBalance/BalanceTransaction writes.
      await CashierService.ensureTableExists(tx, tableId, tableMeta);

      // 1. Check idempotency
      const existingTx = await tx.balanceTransaction.findUnique({
        where: { externalRef },
      });
      if (existingTx) {
         // Already processed, return current balance
         const currentBal = await tx.playerBalance.findUnique({
             where: { tableId_userId: { tableId, userId } }
         });
         return { success: true, newTableBalance: currentBal?.balanceCents ?? 0 };
      }

      // 2. Atomically debit only if bankroll is sufficient. This avoids
      // double-success races where two concurrent buy-ins read the same balance.
      const debitResult = await tx.user.updateMany({
        where: { id: userId, bankrollCents: { gte: amountCents } },
        data: { bankrollCents: { decrement: amountCents } },
      });
      if (debitResult.count !== 1) {
        throw new Error("INSUFFICIENT_BANKROLL");
      }

      // 4. Credit/Upsert PlayerBalance
      const pb = await tx.playerBalance.upsert({
        where: { tableId_userId: { tableId, userId } },
        create: {
          id: nanoid(),
          tableId,
          userId,
          balanceCents: amountCents,
          status: "ACTIVE",
        },
        update: {
          balanceCents: { increment: amountCents },
          status: "ACTIVE",
        },
      });

      // 5. Record Transaction
      await tx.balanceTransaction.create({
        data: {
          id: nanoid(),
          userId,
          tableId,
          type: "BUYIN",
          amountCents,
          externalRef,
        },
      });

      return { success: true, newTableBalance: pb.balanceCents };
    });
  }

  /**
   * Cash Game Cash-Out
   * Atomically debits PlayerBalance and credits User.bankrollCents.
   */
  static async processCashGameCashOut(params: {
    userId: string;
    tableId: string;
    amountCents: number;
    externalRef: string;
    tableMeta: { name: string; creatorId?: string };
  }): Promise<{ success: boolean }> {
    const prisma = getPrisma();
    const { userId, tableId, amountCents, externalRef, tableMeta } = params;

    return await prisma.$transaction(async (tx: any) => {
       // Ensure FK target exists for BalanceTransaction writes.
       await CashierService.ensureTableExists(tx, tableId, tableMeta);

       // 1. Idempotency Check
       const existingTx = await tx.balanceTransaction.findUnique({
        where: { externalRef },
      });
      if (existingTx) {
          return { success: true };
      }

      // 2. Validate current table balance
      const pb = await tx.playerBalance.findUnique({
          where: { tableId_userId: { tableId, userId } }
      });

      if (!pb || pb.balanceCents < amountCents) {
          // In a forceful cashout (all-in), this shouldn't happen unless race condition
          // If we are cashing out *all*, amountCents should match pb.balanceCents
          throw new Error("INSUFFICIENT_TABLE_BALANCE"); 
      }

      // 3. Debit PlayerBalance (Set to 0 if full cashout, or decrement)
      // Usually cashout is "leave table", so we might want to set status too
      const remaining = pb.balanceCents - amountCents;
      await tx.playerBalance.update({
          where: { tableId_userId: { tableId, userId } },
          data: { 
              balanceCents: { decrement: amountCents },
              status: remaining === 0 ? "CASHED_OUT" : "ACTIVE"
          }
      });

      // 4. Credit User
      await tx.user.update({
          where: { id: userId },
          data: { bankrollCents: { increment: amountCents } }
      });

      // 5. Record Transaction
      await tx.balanceTransaction.create({
          data: {
              id: nanoid(),
              userId,
              tableId,
              type: "CASHOUT",
              amountCents,
              externalRef,
          }
      });

      return { success: true };
    });
  }

  /**
   * Tournament Register
   * Debits User.bankrollCents (Fee), Credits Tournament.prizePool (Fee).
   * Rake is implicitly handled if entryFee includes it, or separately if passed.
   * For now: entryFeeCents goes to prize pool.
   */
  static async processTournamentRegister(params: {
      userId: string;
      tournamentId: string;
      entryFeeCents: number;
      externalRef: string;
  }): Promise<{ success: boolean }> {
      const prisma = getPrisma();
      const { userId, tournamentId, entryFeeCents, externalRef } = params;

      return await prisma.$transaction(async (tx: any) => {
           // 1. Idempotency
           const existingRef = await tx.balanceTransaction.findUnique({ where: { externalRef } });
           if(existingRef) return { success: true };

           // 2. Check Bankroll
           const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
           if (user.bankrollCents < entryFeeCents) {
               throw new Error("INSUFFICIENT_BANKROLL");
           }

           // 3. Check Tournament State
           const tourney = await tx.tournament.findUniqueOrThrow({ where: { id: tournamentId }});
           if (tourney.status !== "REGISTERING" && tourney.status !== "LATE_REG") {
               throw new Error("TOURNAMENT_CLOSED");
           }

           // 4. Debit User
           await tx.user.update({
               where: { id: userId },
               data: { bankrollCents: { decrement: entryFeeCents } }
           });

           // 5. Credit Tournament Prize Pool
           await tx.tournament.update({
               where: { id: tournamentId },
               data: { prizePoolCents: { increment: entryFeeCents } }
           });

           // 6. Create Registration
           await tx.tournamentRegistration.create({
               data: {
                   userId,
                   tournamentId,
                   entryTxId: externalRef
               }
           });

           // 7. Record Transaction
           await tx.balanceTransaction.create({
               data: {
                   id: nanoid(),
                   userId,
                   tournamentId,
                   type: "TOURNAMENT_ENTRY",
                   amountCents: entryFeeCents,
                   externalRef,
               }
           });

           return { success: true };
      });
  }
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { Dealer } from "./Dealer.js";
import { PokerState } from "../state/PokerState.js";
import { PlayerState } from "../state/PlayerState.js";
import { CashierService } from "./economy/CashierService.js";
import { assertStateInvariants } from "./invariants/assertState.js";
import { getActionableToActSeatFindingFromState, getStateMoneyFindings } from "./invariants/churnInvariantContract.js";

function makePlayer(input: {
  id: string;
  seat: number;
  stackCents: number;
  status: PlayerState["status"];
  needsAction?: boolean;
  roundBetCents?: number;
  committedCents?: number;
  connected?: boolean;
}): PlayerState {
  const p = new PlayerState();
  p.id = input.id;
  p.userId = input.id;
  p.kind = "HUMAN";
  p.name = input.id;
  p.seat = input.seat;
  p.stackCents = input.stackCents;
  p.status = input.status;
  p.needsAction = input.needsAction ?? false;
  p.roundBetCents = input.roundBetCents ?? 0;
  p.committedCents = input.committedCents ?? 0;
  p.connected = input.connected ?? true;
  return p;
}

function sumPayouts(payoutsByUserId: Record<string, number> | undefined): number {
  return Object.values(payoutsByUserId ?? {}).reduce((sum, value) => sum + value, 0);
}

function assertChurnStateInvariants(state: PokerState): void {
  expect(getStateMoneyFindings(state)).toEqual([]);
  expect(getActionableToActSeatFindingFromState(state)).toBeNull();
}

async function createDealerWithPlayers(count: number): Promise<{ dealer: Dealer; state: PokerState }> {
  const state = new PokerState();
  state.tableId = "table_fold_regression";
  state.maxSeats = 6;
  state.smallBlindCents = 50;
  state.bigBlindCents = 100;
  state.minBuyInCents = 2000;
  state.maxBuyInCents = 20000;

  const dealer = new Dealer(state);
  (dealer as any).scheduleNextHand = () => {};

  for (let i = 0; i < count; i += 1) {
    const id = `u${i + 1}`;
    await dealer.addPlayer(id, id, 5000);
  }

  return { dealer, state };
}

describe("hand-end fold detection regressions", () => {
  beforeEach(() => {
    vi.spyOn(CashierService, "processCashGameBuyIn").mockResolvedValue({
      success: true,
      newTableBalance: 5000,
    });
    vi.spyOn(CashierService, "processCashGameCashOut").mockResolvedValue({ success: true });
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("FOLD-R01: heads-up to-act fold ends hand immediately with valid terminal result", async () => {
    const { dealer, state } = await createDealerWithPlayers(2);
    const handId = state.handId;
    const toActUserId = state.seats[state.toActSeat];

    await dealer.handleAction(toActUserId!, { action: "FOLD" });

    const result = (dealer as any).lastHandResult as
      | { handId: string; reason: "LAST_PLAYER" | "SHOWDOWN"; potCents: number; payoutsByUserId: Record<string, number>; winnerId?: string }
      | undefined;

    expect(state.street).toBe("WAITING");
    expect(result?.handId).toBe(handId);
    expect(result?.reason).toBe("LAST_PLAYER");
    expect(result?.winnerId).toBeTruthy();
    expect(sumPayouts(result?.payoutsByUserId)).toBe(result?.potCents ?? -1);
    assertChurnStateInvariants(state);
    expect(() => assertStateInvariants(state)).not.toThrow();
  });

  it("FOLD-R01B: last-standing result includes uncalled return chips in payout totals", async () => {
    const state = new PokerState();
    state.tableId = "table_fold_uncalled_return";
    state.maxSeats = 6;
    state.smallBlindCents = 50;
    state.bigBlindCents = 100;
    state.street = "PREFLOP";
    state.handId = "hand_fold_uncalled_return";
    state.handNumber = 2;
    state.toActSeat = 0;
    state.roundCurrentBetCents = 100;
    state.potCents = 150;
    state.initialChipMassCents = 15000;
    state.seats.push("u1", "u2", "", "", "", "");

    const folder = makePlayer({
      id: "u1",
      seat: 0,
      stackCents: 9950,
      status: "ACTIVE",
      roundBetCents: 50,
      committedCents: 50,
      needsAction: true,
    });
    const bettor = makePlayer({
      id: "u2",
      seat: 1,
      stackCents: 4900,
      status: "ACTIVE",
      roundBetCents: 100,
      committedCents: 100,
      needsAction: false,
    });
    state.playersById.set(folder.id, folder);
    state.playersById.set(bettor.id, bettor);

    const dealer = new Dealer(state);
    (dealer as any).scheduleNextHand = () => {};

    await dealer.handleAction("u1", { action: "FOLD" });

    const result = (dealer as any).lastHandResult as
      | { handId: string; reason: "LAST_PLAYER" | "SHOWDOWN"; winnerId?: string; potCents: number; payoutsByUserId: Record<string, number> }
      | undefined;

    expect(result?.reason).toBe("LAST_PLAYER");
    expect(result?.winnerId).toBe("u2");
    expect(result?.payoutsByUserId?.u2).toBe(150);
    expect(sumPayouts(result?.payoutsByUserId)).toBe(result?.potCents ?? -1);
    assertChurnStateInvariants(state);
    expect(() => assertStateInvariants(state)).not.toThrow();
  });

  it("FOLD-R02: in 3-way hand, non-final fold does not end hand early", async () => {
    const { dealer, state } = await createDealerWithPlayers(2);
    await dealer.addPlayer("u3", "u3", 5000);

    const warmupToActUserId = state.seats[state.toActSeat];
    await dealer.handleAction(warmupToActUserId!, { action: "FOLD" });
    expect(state.street).toBe("WAITING");

    await dealer.forceAdvanceToNextHandForTest();
    expect(state.playersById.get("u3")?.status).toBe("ACTIVE");

    const handId = state.handId;
    const toActUserId = state.seats[state.toActSeat];

    await dealer.handleAction(toActUserId!, { action: "FOLD" });

    const result = (dealer as any).lastHandResult as { handId: string } | undefined;
    expect(state.street).not.toBe("WAITING");
    expect(result?.handId).not.toBe(handId);
    assertChurnStateInvariants(state);
    expect(() => assertStateInvariants(state)).not.toThrow();
  });

  it("FOLD-R03: last eligible actor folding after prior all-in ends hand correctly", async () => {
    const state = new PokerState();
    state.tableId = "table_fold_last_eligible";
    state.maxSeats = 6;
    state.smallBlindCents = 50;
    state.bigBlindCents = 100;
    state.street = "TURN";
    state.handId = "hand_fold_last_eligible";
    state.handNumber = 8;
    state.toActSeat = 1;
    state.roundCurrentBetCents = 500;
    state.potCents = 3000;
    state.initialChipMassCents = 8000;
    state.seats.push("u1", "u2", "u3", "", "", "");

    const allIn = makePlayer({
      id: "u1",
      seat: 0,
      stackCents: 0,
      status: "ALL_IN",
      roundBetCents: 500,
      committedCents: 1000,
      needsAction: false,
    });
    const lastEligible = makePlayer({
      id: "u2",
      seat: 1,
      stackCents: 2000,
      status: "ACTIVE",
      roundBetCents: 500,
      committedCents: 1000,
      needsAction: true,
    });
    const folded = makePlayer({
      id: "u3",
      seat: 2,
      stackCents: 3000,
      status: "FOLDED",
      roundBetCents: 500,
      committedCents: 1000,
      needsAction: false,
    });

    state.playersById.set(allIn.id, allIn);
    state.playersById.set(lastEligible.id, lastEligible);
    state.playersById.set(folded.id, folded);

    const dealer = new Dealer(state);
    (dealer as any).scheduleNextHand = () => {};

    await dealer.handleAction("u2", { action: "FOLD" });

    const result = (dealer as any).lastHandResult as
      | { handId: string; reason: "LAST_PLAYER" | "SHOWDOWN"; winnerId?: string; potCents: number; payoutsByUserId: Record<string, number> }
      | undefined;

    expect(state.street).toBe("WAITING");
    expect(result?.reason).toBe("LAST_PLAYER");
    expect(result?.winnerId).toBe("u1");
    expect(sumPayouts(result?.payoutsByUserId)).toBe(result?.potCents ?? -1);
    assertChurnStateInvariants(state);
    expect(() => assertStateInvariants(state)).not.toThrow();
  });

  it("FOLD-R04: manual/forced/auto folds converge to equivalent terminal money outcome", async () => {
    const runScenario = async (origin: "PLAYER" | "FORCED" | "AUTO") => {
      const state = new PokerState();
      state.tableId = `table_fold_origin_${origin}`;
      state.maxSeats = 6;
      state.smallBlindCents = 50;
      state.bigBlindCents = 100;
      state.street = "RIVER";
      state.handId = `hand_fold_origin_${origin}`;
      state.handNumber = 9;
      state.toActSeat = 0;
      state.roundCurrentBetCents = 400;
      state.potCents = 1600;
      state.initialChipMassCents = 6200;
      state.seats.push("u1", "u2", "", "", "", "");

      const actor = makePlayer({
        id: "u1",
        seat: 0,
        stackCents: 2400,
        status: "ACTIVE",
        roundBetCents: 400,
        committedCents: 800,
        needsAction: true,
      });
      const other = makePlayer({
        id: "u2",
        seat: 1,
        stackCents: 2200,
        status: "ACTIVE",
        roundBetCents: 400,
        committedCents: 800,
        needsAction: false,
      });
      state.playersById.set(actor.id, actor);
      state.playersById.set(other.id, other);

      const dealer = new Dealer(state);
      (dealer as any).scheduleNextHand = () => {};

      if (origin === "PLAYER") {
        await dealer.handleAction("u1", { action: "FOLD" });
      } else if (origin === "AUTO") {
        await (dealer as any)._handleAction("u1", { action: "FOLD" }, "AUTO");
      } else {
        await (dealer as any).forceFoldForLeave("u1");
      }

      const result = (dealer as any).lastHandResult as
        | { reason: "LAST_PLAYER" | "SHOWDOWN"; potCents: number; winnerId?: string; payoutsByUserId: Record<string, number> }
        | undefined;

      return {
        reason: result?.reason,
        winnerId: result?.winnerId,
        potCents: result?.potCents,
        totalPayout: sumPayouts(result?.payoutsByUserId),
      };
    };

    const manual = await runScenario("PLAYER");
    const forced = await runScenario("FORCED");
    const auto = await runScenario("AUTO");

    expect(manual).toEqual(forced);
    expect(manual).toEqual(auto);
  });

  it("FOLD-R05: fold during reconnect churn emits exactly one HAND_END transition", async () => {
    const reasons: string[] = [];
    const state = new PokerState();
    state.tableId = "table_fold_reconnect_churn";
    state.maxSeats = 6;
    state.smallBlindCents = 50;
    state.bigBlindCents = 100;
    state.minBuyInCents = 2000;
    state.maxBuyInCents = 20000;

    const dealer = new Dealer(state, undefined, {
      onTableSnapshotEmitted: ({ reason }) => {
        reasons.push(reason);
      },
    });
    (dealer as any).scheduleNextHand = () => {};

    await dealer.addPlayer("u1", "u1", 5000);
    await dealer.addPlayer("u2", "u2", 5000);

    const disconnectedUserId = state.seats[state.toActSeat]!;
    await dealer.markDisconnectedSerialized(disconnectedUserId, Date.now() + 60_000);
    await dealer.markReconnectedSerialized(disconnectedUserId);
    if (state.street === "WAITING") {
      await dealer.forceAdvanceToNextHandForTest();
    }
    const started = Date.now();
    while (Date.now() - started < 4000) {
      if (state.street !== "WAITING" && state.seats[state.toActSeat]) break;
      await new Promise((r) => setTimeout(r, 25));
    }

    const handEndBefore = reasons.filter((r) => r === "HAND_END").length;
    const currentToActUserId = state.seats[state.toActSeat]!;
    await dealer.handleAction(currentToActUserId, { action: "FOLD" });
    const handEndAfter = reasons.filter((r) => r === "HAND_END").length;

    expect(handEndAfter - handEndBefore).toBe(1);
    assertChurnStateInvariants(state);
    expect(() => assertStateInvariants(state)).not.toThrow();
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { Dealer } from "./Dealer.js";
import { CashierService } from "./economy/CashierService.js";
import { PokerState } from "../state/PokerState.js";

function makeState(tableId: string): PokerState {
  const state = new PokerState();
  state.tableId = tableId;
  state.tableName = tableId;
  state.maxSeats = 6;
  state.minBuyInCents = 1000;
  state.maxBuyInCents = 20000;
  state.smallBlindCents = 50;
  state.bigBlindCents = 100;
  state.street = "WAITING";
  return state;
}

function sumStacks(state: PokerState): number {
  return [...state.playersById.values()].reduce((sum, player) => sum + player.stackCents, 0);
}

async function finishCurrentHandWithLegalActions(dealer: Dealer, state: PokerState): Promise<void> {
  const deadline = Date.now() + 10_000;
  let guard = 0;
  while (state.street !== "WAITING" && Date.now() < deadline && guard < 200) {
    const toActUserId = state.seats[state.toActSeat];
    expect(toActUserId).toBeTruthy();
    if (!toActUserId) break;

    const options = (dealer as any).buildHeroActionOptions(toActUserId);
    if (options?.canCheck) {
      await dealer.handleAction(toActUserId, { action: "CHECK" });
    } else if (options?.canCall) {
      await dealer.handleAction(toActUserId, { action: "CALL" });
    } else if (options?.canFold) {
      await dealer.handleAction(toActUserId, { action: "FOLD" });
    } else {
      throw new Error("No legal passive action available for to-act player");
    }

    guard += 1;
  }

  expect(state.street).toBe("WAITING");
}

describe("hand money invariant", () => {
  beforeEach(() => {
    vi.spyOn(CashierService, "processCashGameBuyIn").mockImplementation(async ({ amountCents }) => ({
      success: true,
      newTableBalance: amountCents,
    }));
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("conserves chips across a full dealer-driven hand lifecycle", async () => {
    const state = makeState("table_hand_money_invariant");
    const dealer = new Dealer(state);

    await dealer.addPlayer("u1", "Alice", 5000);
    await dealer.addPlayer("u2", "Bob", 5000);

    expect(state.street).not.toBe("WAITING");
    const chipMassBefore = sumStacks(state) + state.potCents;

    await finishCurrentHandWithLegalActions(dealer, state);

    // In this engine, chip mass is fully represented in stacks at hand end.
    expect(sumStacks(state)).toBe(chipMassBefore);
    for (const player of state.playersById.values()) {
      expect(player.stackCents).toBeGreaterThanOrEqual(0);
    }
  });
});

import { describe, expect, it, vi } from "vitest";
import type { TableSnapshotPayload } from "@poker-champ/realtime-contract";
import { Dealer } from "./Dealer.js";
import { PokerState } from "../state/PokerState.js";
import { PlayerState } from "../state/PlayerState.js";

function makePlayer(id: string, seat: number, stackCents: number): PlayerState {
  const p = new PlayerState();
  p.id = id;
  p.userId = id;
  p.kind = "HUMAN";
  p.name = id;
  p.seat = seat;
  p.status = "ACTIVE";
  p.stackCents = stackCents;
  p.roundBetCents = 0;
  p.committedCents = 0;
  p.needsAction = false;
  p.connected = true;
  p.disconnectDeadlineTs = 0;
  return p;
}

describe("hand start stack regression guard", () => {
  it("new deal only changes stacks by posted blinds and never drops non-blind players to zero", async () => {
    const setTimeoutSpy = vi.spyOn(globalThis, "setTimeout").mockImplementation(
      ((handler: TimerHandler) => {
        if (typeof handler === "function") handler();
        return 0 as unknown as ReturnType<typeof setTimeout>;
      }) as unknown as typeof setTimeout,
    );

    try {
    const state = new PokerState();
    state.tableId = "table_stack_zero_regression";
    state.maxSeats = 6;
    state.smallBlindCents = 50;
    state.bigBlindCents = 100;
    state.minBuyInCents = 200;
    state.maxBuyInCents = 50000;
    state.street = "WAITING";
    state.seats.push("u1", "u2", "u3", "u4", "u5", "u6");

    // Include short stacks so blind-capping-to-zero is tested, but only when justified.
    const initialStacks = [250, 320, 900, 1500, 2300, 4100];
    initialStacks.forEach((stack, i) => {
      const id = `u${i + 1}`;
      state.playersById.set(id, makePlayer(id, i, stack));
    });

    let latestHandStartSnapshot: TableSnapshotPayload | null = null;
    const persistence = {
      enabled: false,
      handHistory: null,
      postBlind: async (args: { currentBalance: number; amountCents: number }) => args.currentBalance - args.amountCents,
      debitBet: async (args: { currentBalance: number; amountCents: number }) => args.currentBalance - args.amountCents,
      creditPayout: async (args: { currentBalance: number; amountCents: number }) => args.currentBalance + args.amountCents,
      assertHandBalanced: async () => {},
    } as any;

    const dealer = new Dealer(state, persistence, {
      onTableSnapshotEmitted: ({ reason, payloadJson }) => {
        if (reason === "HAND_START") latestHandStartSnapshot = payloadJson;
      },
    });
    (dealer as any).scheduleNextHand = () => {};

    const handsToExercise = 2;

    for (let hand = 1; hand <= handsToExercise; hand++) {
      const playersWithChips = [...state.playersById.values()].filter((p) => p.status !== "OUT" && p.stackCents > 0);
      if (playersWithChips.length < 2) break;

      const beforeStacks = new Map<string, number>();
      for (const [id, p] of state.playersById.entries()) beforeStacks.set(id, p.stackCents);
      latestHandStartSnapshot = null;

      await (dealer as any).startHand();
      if (state.street === "WAITING") break;

      const trace = [`hand=${hand}`, `handId=${state.handId}`, `sbSeat=${state.sbSeat}`, `bbSeat=${state.bbSeat}`];

      // At hand start, each player's stack delta must match only their posted blind (roundBetCents).
      for (const [id, p] of state.playersById.entries()) {
        const before = beforeStacks.get(id) ?? 0;
        const expectedAfter = before - p.roundBetCents;
        expect(
          p.stackCents,
          `unexpected start-of-hand stack delta user=${id} before=${before} roundBet=${p.roundBetCents} ${trace.join("|")}`,
        ).toBe(expectedAfter);

        if (p.stackCents === 0) {
          expect(
            p.roundBetCents,
            `stack reached zero without full blind contribution user=${id} before=${before} ${trace.join("|")}`,
          ).toBe(before);
        }
      }

      const sbId = state.seats[state.sbSeat];
      const bbId = state.seats[state.bbSeat];
      for (const [id, p] of state.playersById.entries()) {
        if (id === sbId || id === bbId) continue;
        expect(
          p.roundBetCents,
          `non-blind player posted chips at hand start user=${id} ${trace.join("|")}`,
        ).toBe(0);
      }

      // Snapshot must reflect runtime stacks (protects against false UI stack zero payloads).
      expect(latestHandStartSnapshot, `missing HAND_START snapshot ${trace.join("|")}`).toBeTruthy();
      const snapshot = latestHandStartSnapshot!;
      for (const seatSnap of snapshot.seats) {
        if (!seatSnap.userId) continue;
        const runtime = state.playersById.get(seatSnap.userId);
        if (!runtime) continue;
        expect(
          seatSnap.stackCents,
          `snapshot/runtime stack mismatch user=${seatSnap.userId} ${trace.join("|")}`,
        ).toBe(runtime.stackCents);
      }

      // This regression guard targets start-of-hand deltas only.
      // Force next cycle to WAITING so we can exercise repeated deal starts quickly.
      state.street = "WAITING";
      state.runoutMode = "NONE";
    }
    } finally {
      setTimeoutSpy.mockRestore();
    }
  }, 120_000);
});

import type { TableSnapshotPayload } from "@poker-champ/realtime-contract";
import type { PokerState } from "../../state/PokerState.js";
import { eligibleToAct } from "../rules/BettingRound.js";

const NON_ACTIONABLE_SNAPSHOT_REASONS = new Set<TableSnapshotPayload["reason"]>([
  "RUNOUT_STAGE",
  "HAND_END",
  "HAND_SHOWDOWN",
]);

export function getStateMoneyFindings(state: PokerState): string[] {
  const findings: string[] = [];
  if (state.potCents < 0) findings.push(`negative pot ${state.potCents}`);
  for (const player of state.playersById.values()) {
    if (player.stackCents < 0) findings.push(`negative stack user=${player.id} stack=${player.stackCents}`);
    if (player.roundBetCents < 0) findings.push(`negative roundBet user=${player.id} roundBet=${player.roundBetCents}`);
    if (player.committedCents < 0) findings.push(`negative committed user=${player.id} committed=${player.committedCents}`);
  }
  return findings;
}

export function isActionableStatePhase(state: PokerState): boolean {
  if (state.street === "WAITING" || state.street === "SHOWDOWN") return false;
  if (state.runoutMode === "STAGED") return false;
  for (const player of state.playersById.values()) {
    if (eligibleToAct(player) && player.needsAction) return true;
  }
  return false;
}

export function isSameHandActive(
  state: Pick<PokerState, "street" | "handId">,
  handIdBefore: string | null | undefined,
): boolean {
  if (!handIdBefore || !state.handId) return false;
  return state.handId === handIdBefore && state.street !== "WAITING";
}

export function getActionableToActSeatFindingFromState(state: PokerState): string | null {
  if (!isActionableStatePhase(state)) return null;
  const userId = state.seats[state.toActSeat];
  if (!userId) return `missing toActSeat occupant seat=${state.toActSeat}`;
  const player = state.playersById.get(userId);
  if (!player) return `toActSeat user missing from playersById seat=${state.toActSeat} user=${userId}`;
  if (!eligibleToAct(player)) return `toActSeat must be ACTIVE seat=${state.toActSeat} user=${userId} status=${player.status}`;
  if (!player.needsAction) return `toActSeat must have needsAction=true seat=${state.toActSeat} user=${userId}`;
  return null;
}

export function getSnapshotMoneyFindings(snapshot: TableSnapshotPayload): string[] {
  const findings: string[] = [];
  const potCents = snapshot.hand?.potCents ?? 0;
  if (potCents < 0) findings.push(`negative pot snapshot=${snapshot.snapshotId} pot=${potCents}`);
  for (const seat of snapshot.seats) {
    if (seat.stackCents < 0) findings.push(`negative stack seat=${seat.seat} snapshot=${snapshot.snapshotId}`);
    if (seat.roundBetCents < 0) findings.push(`negative roundBet seat=${seat.seat} snapshot=${snapshot.snapshotId}`);
    if (seat.committedCents < 0) findings.push(`negative committed seat=${seat.seat} snapshot=${snapshot.snapshotId}`);
  }
  return findings;
}

export function isActionableSnapshotPhase(snapshot: Pick<TableSnapshotPayload, "hand" | "reason" | "lastHandResult">): boolean {
  if (!snapshot.hand) return false;
  if (snapshot.hand.street === "WAITING" || snapshot.hand.street === "SHOWDOWN") return false;
  if (NON_ACTIONABLE_SNAPSHOT_REASONS.has(snapshot.reason)) return false;
  if (snapshot.lastHandResult?.handId && snapshot.lastHandResult.handId === snapshot.hand.handId) return false;
  return true;
}

export function getActionableToActSeatFindingFromSnapshot(snapshot: TableSnapshotPayload): string | null {
  if (!isActionableSnapshotPhase(snapshot)) return null;
  const toActSeat = snapshot.hand?.toActSeat;
  if (typeof toActSeat !== "number") return `missing toActSeat snapshot=${snapshot.snapshotId}`;
  const seat = snapshot.seats.find((s:any) => s.seat === toActSeat);
  if (!seat?.occupied) return `toActSeat points to empty seat snapshot=${snapshot.snapshotId} seat=${toActSeat}`;
  if (seat.status !== "ACTIVE") {
    return `toActSeat must be ACTIVE snapshot=${snapshot.snapshotId} seat=${toActSeat} status=${seat.status}`;
  }
  return null;
}

