    playerB.status = "ABANDONED"; // B is abandoned
    playerB.connected = false;
    playerB.roundBetCents = 0;
    playerB.committedCents = 0;
    playerB.needsAction = false;
    
    const playerA = new PlayerState();
    playerA.id = "A";
