import type { PrismaClient } from "@prisma/client";
import { nanoid } from "nanoid";
import type { Street } from "../../state/PokerState.js";

/**
 * LedgerService - Sole Authority for In-Hand Chip Movement
 * 
 * Responsibilities:
 * - Manage PlayerBalance.balanceCents for in-hand transactions
 * - Create comprehensive BalanceTransaction audit trail
 * - Enforce hand balance (debits = credits)
 * - Use deterministic externalRef for crash recovery
 * 
 * Rules:
 * - NEVER touches User.bankrollCents (that's CashierService's job)
 * - ALL in-hand chip movements must go through this service
 * - Dealer must use returned balance to set PlayerState.stackCents
 * - PlayerState.stackCents is a read-only mirror of PlayerBalance
 */
export class LedgerService {
  constructor(private prisma: PrismaClient, private tableId: string) {}

  /**
   * Get current balance for a user at this table
   */
  async getBalance(userId: string): Promise<number> {
    const bal = await this.prisma.playerBalance.findUnique({
      where: { tableId_userId: { tableId: this.tableId, userId } },
      select: { balanceCents: true },
    });
    return bal?.balanceCents ?? 0;
  }

  /**
   * Ensure PlayerBalance records exist for all users
   * Called at table join (after CashierService buy-in)
   */
  async ensureBalances(userIds: string[], initialBalanceByUserId: Record<string, number>) {
    for (const userId of userIds) {
      await this.prisma.playerBalance.upsert({
        where: { tableId_userId: { tableId: this.tableId, userId } },
        create: {
          id: nanoid(),
          tableId: this.tableId,
          userId,
          balanceCents: initialBalanceByUserId[userId] ?? 0,
          status: "ACTIVE",
        },
        update: {},
      });
    }
  }

  /**
   * Post blind (SB or BB)
   * Returns new balance
   */
  async postBlind(params: {
    userId: string;
    handId: string;
    blindType: "SB" | "BB";
    amountCents: number;
  }): Promise<number> {
    const externalRef = `blind_${params.blindType.toLowerCase()}_${this.tableId}_${params.userId}_${params.handId}`;
    
    return await this.debit({
      userId: params.userId,
      handId: params.handId,
      type: `BLIND_${params.blindType}`,
      amountCents: params.amountCents,
      externalRef,
    });
  }

  /**
   * Debit for bet, raise, call, or all-in
   * Returns new balance
   */
  async debitBet(params: {
    userId: string;
    handId: string;
    street: Street;
    action: "BET" | "RAISE" | "CALL" | "ALL_IN";
    amountCents: number;
    sequenceNum: number;
  }): Promise<number> {
    const externalRef = `${params.action.toLowerCase()}_${this.tableId}_${params.userId}_${params.handId}_${params.street.toLowerCase()}_${params.sequenceNum}`;
    
    return await this.debit({
      userId: params.userId,
      handId: params.handId,
      type: params.action,
      amountCents: params.amountCents,
      externalRef,
      metaJson: { street: params.street, sequenceNum: params.sequenceNum },
    });
  }

  /**
   * Credit refund (e.g., uncalled bet)
   * Returns new balance
   */
  async creditRefund(params: {
    userId: string;
    handId: string;
    amountCents: number;
    reason: string;
  }): Promise<number> {
    const externalRef = `refund_${this.tableId}_${params.userId}_${params.handId}`;
    
    return await this.credit({
      userId: params.userId,
      handId: params.handId,
      type: "REFUND",
      amountCents: params.amountCents,
      externalRef,
      metaJson: { reason: params.reason },
    });
  }

  /**
   * Credit payout from pot
   * Returns new balance
   */
  async creditPayout(params: {
    userId: string;
    handId: string;
    amountCents: number;
    potIndex?: number;
  }): Promise<number> {
    const potSuffix = params.potIndex !== undefined ? `_pot${params.potIndex}` : "";
    const externalRef = `payout_${this.tableId}_${params.userId}_${params.handId}${potSuffix}`;
    
    return await this.credit({
      userId: params.userId,
      handId: params.handId,
      type: "PAYOUT",
      amountCents: params.amountCents,
      externalRef,
      metaJson: params.potIndex !== undefined ? { potIndex: params.potIndex } : undefined,
    });
  }

  /**
   * Assert that hand is balanced (total debits = total credits)
   * Throws error if not balanced.
   * Only considers in-hand transaction types.
   */
  async assertHandBalanced(handId: string): Promise<void> {
    const handTypes = [
      "BLIND_SB",
      "BLIND_BB",
      "BET",
      "RAISE",
      "CALL",
      "ALL_IN",
      "REFUND",
      "PAYOUT",
    ];

    const txs = await this.prisma.balanceTransaction.findMany({
      where: { 
        tableId: this.tableId, 
        handId,
        type: { in: handTypes }
      },
    });

    const sum = txs.reduce((acc: number, tx: any) => acc + tx.amountCents, 0);

    if (sum !== 0) {
      const history = txs.map((t: any) => `${t.type}:${t.userId}:${t.amountCents}`).join(", ");
      const msg = `LEDGER_MISMATCH: Hand ${handId} is unbalanced by ${sum} cents. History: [${history}]`;
      console.error(msg);
      throw new Error(msg);
    }
  }

  /**
   * Internal: Debit operation
   * Negative amountCents, decreases balance
   */
  private async debit(params: {
    userId: string;
    handId: string;
    type: string;
    amountCents: number;
    externalRef: string;
    metaJson?: any;
  }): Promise<number> {
    return await this.applyTransaction({
      ...params,
      amountCents: -Math.abs(params.amountCents), // Ensure negative
    });
  }

  /**
   * Internal: Credit operation
   * Positive amountCents, increases balance
   */
  private async credit(params: {
    userId: string;
    handId: string;
    type: string;
    amountCents: number;
    externalRef: string;
    metaJson?: any;
  }): Promise<number> {
    return await this.applyTransaction({
      ...params,
      amountCents: Math.abs(params.amountCents), // Ensure positive
    });
  }

  /**
   * Internal: Apply transaction with idempotency
   */
  private async applyTransaction(params: {
    userId: string;
    handId: string;
    type: string;
    amountCents: number;
    externalRef: string;
    metaJson?: any;
  }): Promise<number> {
    // Check idempotency
    const existing = await this.prisma.balanceTransaction.findUnique({
      where: { externalRef: params.externalRef },
    });

    if (existing) {
      // Already processed, return current balance
      return await this.getBalance(params.userId);
    }

    // Get current balance
    const current = await this.getBalance(params.userId);
    const next = current + params.amountCents;

    // Prevent negative balance
    if (next < 0) {
      throw new Error(
        `INSUFFICIENT_BALANCE: User ${params.userId} has ${current} cents, cannot debit ${Math.abs(params.amountCents)} cents`
      );
    }

    // Update PlayerBalance
    await this.prisma.playerBalance.upsert({
      where: { tableId_userId: { tableId: this.tableId, userId: params.userId } },
      create: {
        id: nanoid(),
        tableId: this.tableId,
        userId: params.userId,
        balanceCents: next,
        status: "ACTIVE",
      },
      update: { balanceCents: next },
    });

    // Record transaction
    await this.prisma.balanceTransaction.create({
      data: {
        id: nanoid(),
        tableId: this.tableId,
        userId: params.userId,
        handId: params.handId,
        type: params.type,
        amountCents: params.amountCents,
        externalRef: params.externalRef,
        metaJson: params.metaJson ?? undefined,
      },
    });

    return next;
  }

  /**
   * DEPRECATED: Use specific methods instead
   * Kept for backward compatibility during migration
   */
  async applyTx(params: {
    userId: string;
    handId?: string;
    kind: string;
    deltaCents: number;
    meta?: any;
  }) {
    console.warn("LedgerService.applyTx() is deprecated. Use specific methods like postBlind(), debitBet(), etc.");
    
    const externalRef = `legacy_${this.tableId}_${params.userId}_${params.handId}_${Date.now()}`;
    
    return await this.applyTransaction({
      userId: params.userId,
      handId: params.handId ?? "unknown",
      type: params.kind,
      amountCents: params.deltaCents,
      externalRef,
      metaJson: params.meta,
    });
  }
}

import type { PrismaClient } from "@prisma/client";
import { getPrisma } from "@poker-champ/db";
import { HandHistoryService } from "./HandHistoryService.js";
import { LedgerService } from "./LedgerService.js";
import { BotStatsService } from "./BotStatsService.js";
import { logger } from "../../lib/logger.js";
import type { Street } from "../../state/PokerState.js";
import type { PlayerState } from "../../state/PlayerState.js";
import { isLedgerParticipant } from "./ledgerHelpers.js";

/**
 * Persistence facade:
 * - If DATABASE_URL is missing, acts as no-op.
 * - Keeps engine runnable without DB.
 * 
 * Phase 3 - Ledger Authority:
 * This facade remains the entry point for the Dealer, but delegates all 
 * in-hand transactions to LedgerService. It provides in-memory fallbacks
 * if the database is disabled.
 */
export class PersistenceFacade {
  readonly enabled: boolean;
  readonly prisma: PrismaClient | null;
  readonly handHistory: HandHistoryService | null;
  readonly ledger: LedgerService | null;
  readonly botStats: BotStatsService | null;

  constructor(private table:
    | string
    | {
        tableId: string;
        tableName?: string;
        creatorId?: string;
      }) {
    const tableId = typeof table === "string" ? table : table.tableId;
    const tableName = typeof table === "string" ? undefined : table.tableName;
    const creatorId = typeof table === "string" ? undefined : table.creatorId;
    const hasDb = !!process.env.DATABASE_URL && process.env.NODE_ENV !== "test";
    this.enabled = hasDb;

    if (!hasDb) {
      this.prisma = null;
      this.handHistory = null;
      this.ledger = null;
      this.botStats = null;
      return;
    }

    if (!tableName || tableName.trim().length === 0) {
      throw new Error("INVARIANT: tableName required for PokerTable persistence");
    }

    const prisma = getPrisma();
    this.prisma = prisma;
    this.handHistory = new HandHistoryService(prisma, tableId, { name: tableName, creatorId });
    this.ledger = new LedgerService(prisma, tableId);
    this.botStats = new BotStatsService(prisma);
  }

  /**
   * Post blind (SB or BB)
   * If DB disabled or bot, returns currentBalance - amountCents
   */
  async postBlind(params: {
    userId: string;
    handId: string;
    blindType: "SB" | "BB";
    amountCents: number;
    currentBalance: number;
    player: PlayerState;
  }): Promise<number> {
    if (!isLedgerParticipant(params.player)) return params.currentBalance - params.amountCents;
    if (!this.enabled || !this.ledger) return params.currentBalance - params.amountCents;
    try {
      return await this.ledger.postBlind(params);
    } catch (err) {
      logger.error({ err, userId: params.userId, handId: params.handId }, "postBlind failed");
      throw err;
    }
  }

  /**
   * Debit for bet, raise, call, or all-in
   */
  async debitBet(params: {
    userId: string;
    handId: string;
    street: Street;
    action: "BET" | "RAISE" | "CALL" | "ALL_IN";
    amountCents: number;
    sequenceNum: number;
    currentBalance: number;
    player: PlayerState;
  }): Promise<number> {
    if (!isLedgerParticipant(params.player)) return params.currentBalance - params.amountCents;
    if (!this.enabled || !this.ledger) return params.currentBalance - params.amountCents;
    try {
      return await this.ledger.debitBet({
        userId: params.userId,
        handId: params.handId,
        street: params.street,
        action: params.action,
        amountCents: params.amountCents,
        sequenceNum: params.sequenceNum,
      });
    } catch (err) {
      logger.error({ err, userId: params.userId, handId: params.handId }, "debitBet failed");
      throw err;
    }
  }

  /**
   * Credit refund (e.g., uncalled bet)
   */
  async creditRefund(params: {
    userId: string;
    handId: string;
    amountCents: number;
    reason: string;
    currentBalance: number;
    player: PlayerState;
  }): Promise<number> {
    if (!isLedgerParticipant(params.player)) return params.currentBalance + params.amountCents;
    if (!this.enabled || !this.ledger) return params.currentBalance + params.amountCents;
    try {
      return await this.ledger.creditRefund({
        userId: params.userId,
        handId: params.handId,
        amountCents: params.amountCents,
        reason: params.reason,
      });
    } catch (err) {
      logger.error({ err, userId: params.userId, handId: params.handId }, "creditRefund failed");
      throw err;
    }
  }

  /**
   * Credit payout from pot
   */
  async creditPayout(params: {
    userId: string;
    handId: string;
    amountCents: number;
    potIndex?: number;
    currentBalance: number;
    player: PlayerState;
  }): Promise<number> {
    if (!isLedgerParticipant(params.player)) return params.currentBalance + params.amountCents;
    if (!this.enabled || !this.ledger) return params.currentBalance + params.amountCents;
    try {
      return await this.ledger.creditPayout({
        userId: params.userId,
        handId: params.handId,
        amountCents: params.amountCents,
        potIndex: params.potIndex,
      });
    } catch (err) {
      logger.error({ err, userId: params.userId, handId: params.handId }, "creditPayout failed");
      throw err;
    }
  }

  async assertHandBalanced(handId: string): Promise<void> {
    if (!this.enabled || !this.ledger) return;
    try {
      await this.ledger.assertHandBalanced(handId);
    } catch (err) {
      const tableId = typeof this.table === "string" ? this.table : this.table.tableId;
      logger.warn({ err, tableId, handId }, "ledger assertion failed");
      // In many environments we log but don't crash the server.
      // But Phase 3 says "fail hard if debits != credits".
      // We will re-throw here so the Dealer/Room can handle it.
      throw err;
    }
  }

  // DEPRECATED Legacy methods
  async applyBankrollEvent(params: {
    userId: string;
    handId?: string;
    kind: string;
    deltaCents: number;
    meta?: any;
  }): Promise<number | null> {
    if (!this.enabled || !this.ledger) return null;
    return await this.ledger.applyTx(params);
  }

  async debitPlayer(params: {
    userId: string;
    handId?: string;
    kind: string;
    amountCents: number;
    meta?: any;
  }): Promise<number | null> {
    if (!this.enabled || !this.ledger) return null;
    return await this.applyBankrollEvent({
      ...params,
      deltaCents: -Math.abs(params.amountCents),
    });
  }

  async creditPlayer(params: {
    userId: string;
    handId?: string;
    kind: string;
    amountCents: number;
    meta?: any;
  }): Promise<number | null> {
    if (!this.enabled || !this.ledger) return null;
    return await this.applyBankrollEvent({
      ...params,
      deltaCents: Math.abs(params.amountCents),
    });
  }
}

import { TableSnapshotPayloadSchema, type TableSnapshotPayload } from "@poker-champ/realtime-contract";
import { getPrisma } from "@poker-champ/db";
import { toFrameReason } from "../replay/FrameReason.js";

export class ReplayFrameService {
  static async getFramesForHand(handId: string): Promise<TableSnapshotPayload[]> {
    const prisma = getPrisma() as any;
    const rows = await prisma.tableSnapshotLog.findMany({
      where: {
        handId,
        payloadJson: {
          path: "$.hero.userId",
          equals: "SYSTEM",
        },
      },
      select: {
        payloadJson: true,
      },
      orderBy: [{ createdAt: "asc" }],
    });

    const bySeq = new Map<number, TableSnapshotPayload>();
    for (const row of rows as Array<{ payloadJson: unknown }>) {
      const parsed = TableSnapshotPayloadSchema.safeParse(row.payloadJson);
      if (!parsed.success) continue;
      if (toFrameReason(parsed.data.reason) == null) continue;
      if (!bySeq.has(parsed.data.snapshotSeq)) {
        bySeq.set(parsed.data.snapshotSeq, parsed.data);
      }
    }

    return [...bySeq.entries()]
      .sort((a, b) => a[0] - b[0])
      .map(([, payload]) => payload);
  }
}

import { getPrisma } from "@poker-champ/db";
import { logger } from "../../lib/logger.js";

export type SnapshotLogReason =
  | "HAND_START"
  | "ACTION_ACCEPTED"
  | "STREET_TRANSITION"
  | "POT_UPDATED"
  | "SHOWDOWN"
  | "HAND_END"
  | "PLAYER_JOIN"
  | "PLAYER_LEAVE";

export class TableSnapshotLogService {
  private static readonly DEFAULT_PAYLOAD_BYTES_CAP = 256 * 1024;
  private static readonly DEFAULT_SAMPLE_RATE = 1.0;

  private static getPayloadBytesCap(): number {
    const raw = process.env.SNAPSHOT_LOG_MAX_BYTES;
    if (!raw) return TableSnapshotLogService.DEFAULT_PAYLOAD_BYTES_CAP;
    const parsed = Number.parseInt(raw, 10);
    if (!Number.isFinite(parsed) || parsed <= 0) return TableSnapshotLogService.DEFAULT_PAYLOAD_BYTES_CAP;
    return parsed;
  }

  private static getSampleRate(): number {
    const raw = process.env.SNAPSHOT_LOG_SAMPLE_RATE;
    if (!raw) return TableSnapshotLogService.DEFAULT_SAMPLE_RATE;
    const parsed = Number.parseFloat(raw);
    if (!Number.isFinite(parsed)) return TableSnapshotLogService.DEFAULT_SAMPLE_RATE;
    if (parsed <= 0) return 0;
    if (parsed >= 1) return 1;
    return parsed;
  }

  static async writeSnapshot(params: {
    tableId: string;
    handId?: string;
    snapshotId: string;
    reason: SnapshotLogReason;
    street: string;
    payloadJson: unknown;
    stateHash: string;
    schemaVersion: number;
  }): Promise<void> {
    const sampleRate = TableSnapshotLogService.getSampleRate();
    if (sampleRate <= 0 || Math.random() > sampleRate) return;

    let payloadBytes = 0;
    try {
      payloadBytes = Buffer.byteLength(JSON.stringify(params.payloadJson), "utf8");
    } catch (err) {
      logger.warn(
        { err, tableId: params.tableId, snapshotId: params.snapshotId },
        "SNAPSHOT_LOG_SERIALIZE_FAILED",
      );
      return;
    }

    const cap = TableSnapshotLogService.getPayloadBytesCap();
    if (payloadBytes > cap) {
      logger.warn(
        {
          tableId: params.tableId,
          snapshotId: params.snapshotId,
          payloadBytes,
          payloadBytesCap: cap,
        },
        "SNAPSHOT_LOG_SKIPPED_PAYLOAD_TOO_LARGE",
      );
      return;
    }

    const prisma = getPrisma() as any;
    const baseData = {
      tableId: params.tableId,
      snapshotId: params.snapshotId,
      reason: params.reason,
      street: params.street,
      payloadJson: params.payloadJson as any,
      payloadBytes,
      stateHash: params.stateHash,
      schemaVersion: params.schemaVersion,
    };

    try {
      await prisma.tableSnapshotLog.create({
        data: {
          ...baseData,
          handId: params.handId ?? null,
        },
      });
      return;
    } catch (err: any) {
      // Duplicate snapshotId is idempotent/no-op.
      if (err?.code === "P2002") return;
      if (err?.code !== "P2003") throw err;
      const fieldName = String(err?.meta?.field_name ?? "");
      // Table not in DB (e.g. ephemeral/test table) – skip logging.
      if (fieldName.includes("tableId")) {
        logger.warn(
          { tableId: params.tableId, snapshotId: params.snapshotId },
          "SNAPSHOT_LOG_TABLE_NOT_PERSISTED_SKIP",
        );
        return;
      }
      // handId not persisted – retry without handId.
      if (params.handId && fieldName.includes("handId")) {
        logger.warn(
          { tableId: params.tableId, handId: params.handId, snapshotId: params.snapshotId },
          "SNAPSHOT_LOG_HAND_ID_NOT_PERSISTED_FALLBACK",
        );
        await prisma.tableSnapshotLog.create({
          data: { ...baseData, handId: null },
        });
      } else {
        throw err;
      }
    }
  }
}

