import { describe, it, expect, beforeAll, afterAll } from "vitest";
import express from "express";
import http from "node:http";
import { nanoid } from "nanoid";
import { getPrisma } from "@poker-champ/db";
import { handHistoryRouter } from "../HandHistoryRouter.js";
import { createTestUser, createAuthToken, cleanupTestUsers } from "../../__tests__/testUtils.js";

describe("Hand History Security", () => {
  const prisma = getPrisma();
  let server: http.Server;
  let baseUrl: string;

  let userA: { id: string; username: string | null };
  let userB: { id: string; username: string | null };
  let userAToken: string;
  let userBToken: string;

  let tableId: string;
  let playerAId: string;
  let playerBId: string;
  let sharedHandId: string;
  let userBOnlyHandId: string;

  async function get(path: string, token: string | null) {
    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (token) headers.Authorization = `Bearer ${token}`;
    return fetch(`${baseUrl}${path}`, { method: "GET", headers });
  }

  beforeAll(async () => {
    const app = express();
    app.use(express.json());
    app.use("/api/history", handHistoryRouter);

    await new Promise<void>((resolve) => {
      server = app.listen(0, () => {
        const addr = server.address();
        const port = typeof addr === "object" && addr ? addr.port : 0;
        baseUrl = `http://127.0.0.1:${port}`;
        resolve();
      });
    });

    userA = await createTestUser(`history-security-a-${nanoid(6)}`);
    userB = await createTestUser(`history-security-b-${nanoid(6)}`);
    userAToken = await createAuthToken(userA.id);
    userBToken = await createAuthToken(userB.id);

    tableId = `table_${nanoid(8)}`;
    await prisma.pokerTable.create({
      data: { id: tableId, name: "History Security Table", maxSeats: 6 },
    });

    const playerA = await prisma.pokerPlayer.create({
      data: {
        tableId,
        externalId: userA.id,
        userId: userA.id,
        displayName: userA.username ?? "userA",
        seat: 0,
      },
    });
    playerAId = playerA.id;

    const playerB = await prisma.pokerPlayer.create({
      data: {
        tableId,
        externalId: userB.id,
        userId: userB.id,
        displayName: userB.username ?? "userB",
        seat: 1,
      },
    });
    playerBId = playerB.id;

    sharedHandId = `hand_${nanoid(10)}`;
    await prisma.hand.create({
      data: {
        id: sharedHandId,
        tableId,
        dealerSeat: 0,
        smallBlindCents: 50,
        bigBlindCents: 100,
        endedAt: new Date(),
        reason: "SHOWDOWN",
        boardJson: ["Ah", "Kd", "2c", "7s", "9h"],
        players: {
          create: [
            {
              id: nanoid(),
              playerId: playerAId,
              seat: 0,
              startingStackCents: 5000,
              endingStackCents: 5300,
              holeCardsJson: ["As", "Ad"],
            },
            {
              id: nanoid(),
              playerId: playerBId,
              seat: 1,
              startingStackCents: 5000,
              endingStackCents: 4700,
              holeCardsJson: ["Kh", "Kd"],
            },
          ],
        },
      },
    });

    userBOnlyHandId = `hand_${nanoid(10)}`;
    await prisma.hand.create({
      data: {
        id: userBOnlyHandId,
        tableId,
        dealerSeat: 1,
        smallBlindCents: 50,
        bigBlindCents: 100,
        endedAt: new Date(),
        reason: "LAST_PLAYER",
        boardJson: [],
        players: {
          create: {
            id: nanoid(),
            playerId: playerBId,
            seat: 1,
            startingStackCents: 5000,
            endingStackCents: 5050,
            holeCardsJson: ["Qs", "Qd"],
          },
        },
      },
    });
  });

  afterAll(async () => {
    await new Promise<void>((resolve) => server.close(() => resolve()));
    await prisma.handPayout.deleteMany({ where: { handId: { in: [sharedHandId, userBOnlyHandId] } } });
    await prisma.handAction.deleteMany({ where: { handId: { in: [sharedHandId, userBOnlyHandId] } } });
    await prisma.handPlayer.deleteMany({ where: { handId: { in: [sharedHandId, userBOnlyHandId] } } });
    await prisma.hand.deleteMany({ where: { id: { in: [sharedHandId, userBOnlyHandId] } } });
    await prisma.pokerPlayer.deleteMany({ where: { id: { in: [playerAId, playerBId] } } });
    await prisma.pokerTable.deleteMany({ where: { id: tableId } });
    await cleanupTestUsers();
  });

  it("should prevent User A from fetching hand belonging only to User B", async () => {
    const response = await get(`/api/history/hands/${userBOnlyHandId}`, userAToken);
    expect(response.status).toBe(404);
    const data = await response.json();
    expect(data.error).toBe("Hand not found");
  });

  it("should allow User A to fetch hand where A participated", async () => {
    const response = await get(`/api/history/hands/${sharedHandId}`, userAToken);
    expect(response.status).toBe(200);

    const data = await response.json();
    expect(data.id).toBe(sharedHandId);
    expect(Array.isArray(data.players)).toBe(true);
    expect(Array.isArray(data.actions)).toBe(true);
    expect(Array.isArray(data.payouts)).toBe(true);
  });

  it("should prevent unauthorized access without token", async () => {
    const response = await get(`/api/history/hands/${sharedHandId}`, null);
    expect(response.status).toBe(401);
  });

  it("should return 404 for non-existent hand ID", async () => {
    const fakeHandId = `hand_${nanoid(12)}`;
    const response = await get(`/api/history/hands/${fakeHandId}`, userAToken);
    expect(response.status).toBe(404);
    const data = await response.json();
    expect(data.error).toBe("Hand not found");
  });

  it("should validate hand ID max length", async () => {
    const invalidHandId = "x".repeat(192);
    const response = await get(`/api/history/hands/${invalidHandId}`, userAToken);
    expect(response.status).toBe(400);
    const data = await response.json();
    expect(data.error).toBe("Invalid hand ID");
  });
});

import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import express from "express";
import http from "node:http";

const {
  state,
  prismaMock,
} = vi.hoisted(() => {
  type LessonStep = {
    id: string;
    lessonId: string;
    sequence: number;
    type: string;
    questionText: string | null;
    beforeMessage: string | null;
    followUpMessage: string | null;
    gradingSpecJson: Record<string, unknown> | null;
    gradingVersion: number;
    snapshotVersion: number | null;
    snapshotJson: Record<string, unknown> | null;
    options: Array<{
      optionKey: string;
      label: string;
      valueJson: Record<string, unknown> | null;
      displayOrder: number;
    }>;
    concepts: Array<{
      conceptId: string;
      weight: number;
      concept: { code: string; name: string };
    }>;
  };

  const state = {
    lessons: [] as any[],
    steps: [] as LessonStep[],
    attempts: [] as any[],
    attemptSteps: [] as any[],
    mastery: [] as any[],
    lockedLessonIds: new Set<string>(),
  };

  const prismaMock = {
    lesson: {
      findMany: vi.fn(async () =>
        state.lessons
          .filter((l) => l.status === "PUBLISHED")
          .map((l) => ({
            ...l,
            steps: state.steps
              .filter((s) => s.lessonId === l.id)
              .map((s) => ({ id: s.id, sequence: s.sequence, type: s.type })),
          })),
      ),
      findUnique: vi.fn(async ({ where }: any) => {
        const lesson = state.lessons.find((l) => l.id === where.id);
        if (!lesson) return null;
        return {
          ...lesson,
          steps: state.steps
            .filter((s) => s.lessonId === lesson.id)
            .sort((a, b) => a.sequence - b.sequence)
            .map((s) => ({
              ...s,
              options: [...s.options].sort((a, b) => a.displayOrder - b.displayOrder),
            })),
        };
      }),
    },
    userConceptMastery: {
      findMany: vi.fn(async ({ where }: any) =>
        state.mastery
          .filter((m) => m.userId === where.userId)
          .map((m) => ({
            ...m,
            concept: { code: m.code, name: m.name },
          })),
      ),
      findUnique: vi.fn(async ({ where }: any) =>
        state.mastery.find(
          (m) =>
            m.userId === where.userId_conceptId.userId &&
            m.conceptId === where.userId_conceptId.conceptId,
        ) ?? null,
      ),
      upsert: vi.fn(async ({ where, create, update }: any) => {
        const idx = state.mastery.findIndex(
          (m) =>
            m.userId === where.userId_conceptId.userId &&
            m.conceptId === where.userId_conceptId.conceptId,
        );
        if (idx === -1) {
          state.mastery.push({
            ...create,
            code: "position",
            name: "Position",
          });
          return create;
        }
        state.mastery[idx] = { ...state.mastery[idx], ...update };
        return state.mastery[idx];
      }),
    },
    lessonAttempt: {
      findUnique: vi.fn(async ({ where }: any) => {
        const row = state.attempts.find((a) => a.id === where?.id);
        return row
          ? {
              id: row.id,
              lessonId: row.lessonId,
              status: row.status,
              scorePct: row.scorePct,
            }
          : null;
      }),
      findFirst: vi.fn(async ({ where, orderBy }: any) => {
        const rows = state.attempts.filter((a) => (
          (where.id == null || a.id === where.id) &&
          (where.lessonId == null || a.lessonId === where.lessonId) &&
          (where.userId == null || a.userId === where.userId) &&
          (where.status == null || a.status === where.status)
        ));
        if (!rows.length) return null;
        if (orderBy?.startedAt === "desc") {
          const row = [...rows].sort((a, b) => b.startedAt.getTime() - a.startedAt.getTime())[0];
          return {
            ...row,
            steps: state.attemptSteps
              .filter((s) => s.attemptId === row.id)
              .map((s) => ({
                ...s,
                step: state.steps.find((st) => st.id === s.stepId) ?? null,
              })),
          };
        }
        const row = rows[0];
        return {
          ...row,
          steps: state.attemptSteps
            .filter((s) => s.attemptId === row.id)
            .map((s) => ({
              ...s,
              step: state.steps.find((st) => st.id === s.stepId) ?? null,
            })),
        };
      }),
      findMany: vi.fn(async ({ where }: any) => {
        const rows = state.attempts.filter((a) => (
          (where.userId == null || a.userId === where.userId) &&
          (where.lessonId == null
            ? true
            : typeof where.lessonId === "string"
              ? a.lessonId === where.lessonId
              : where.lessonId?.in == null || where.lessonId.in.includes(a.lessonId)) &&
          (where.status == null || a.status === where.status)
        ));
        return [...rows]
          .sort((a, b) => b.startedAt.getTime() - a.startedAt.getTime())
          .map((row) => ({
            ...row,
            steps: state.attemptSteps
              .filter((s) => s.attemptId === row.id)
              .map((s) => ({
                ...s,
                step: state.steps.find((st) => st.id === s.stepId) ?? null,
              })),
          }));
      }),
      create: vi.fn(async ({ data }: any) => {
        const row = {
          ...data,
          startedAt: new Date(),
          completedAt: null,
          scorePct: null,
        };
        state.attempts.push(row);
        return row;
      }),
      update: vi.fn(async ({ where, data }: any) => {
        const idx = state.attempts.findIndex((a) => a.id === where.id);
        if (idx >= 0) state.attempts[idx] = { ...state.attempts[idx], ...data };
        return state.attempts[idx];
      }),
      count: vi.fn(async ({ where }: any) =>
        state.attempts.filter((a) => (
          (where.userId == null || a.userId === where.userId) &&
          (where.status == null || a.status === where.status) &&
          (where.completedAt?.gte == null || (a.completedAt != null && a.completedAt >= where.completedAt.gte))
        )).length,
      ),
      groupBy: vi.fn(async ({ by, where }: any) => {
        const rows = state.attempts.filter((a) => (
          (where?.userId == null || a.userId === where.userId) &&
          (where?.status == null || a.status === where.status)
        ));
        if (Array.isArray(by) && by.length === 1 && by[0] === "lessonId") {
          const lessonIds = Array.from(new Set(rows.map((a) => a.lessonId)));
          return lessonIds.map((lessonId) => ({ lessonId }));
        }
        return [];
      }),
    },
    userCurriculumProgress: {
      upsert: vi.fn(async ({ where, create, update }: any) => ({
        userId: where?.userId ?? create?.userId ?? "user_test_1",
        completedLessonsCount: update?.completedLessonsCount ?? create?.completedLessonsCount ?? 0,
        updatedAt: update?.updatedAt ?? create?.updatedAt ?? new Date(),
      })),
    },
    lessonStep: {
      findFirst: vi.fn(async ({ where }: any) => {
        const step = state.steps.find((s) =>
          (where.id == null || s.id === where.id) &&
          (where.lessonId == null || s.lessonId === where.lessonId),
        );
        return step ?? null;
      }),
      count: vi.fn(async ({ where }: any) =>
        state.steps.filter((s) => (
          (where.lessonId == null || s.lessonId === where.lessonId) &&
          (where.NOT?.type == null || s.type !== where.NOT.type)
        )).length,
      ),
    },
    lessonAttemptStep: {
      findMany: vi.fn(async ({ where }: any) =>
        state.attemptSteps.filter((s) => {
          if (where.attemptId != null) {
            return s.attemptId === where.attemptId;
          }
          if (where.stepId != null) {
            if (s.stepId !== where.stepId) return false;
            if (where.attempt != null) {
              const attempt = state.attempts.find((a) => a.id === s.attemptId);
              if (!attempt) return false;
              if (where.attempt.userId != null && attempt.userId !== where.attempt.userId) return false;
              if (where.attempt.lessonId != null && attempt.lessonId !== where.attempt.lessonId) return false;
              if (where.attempt.status != null && attempt.status !== where.attempt.status) return false;
            }
            return true;
          }
          if (where.step?.lessonId != null) {
            const step = state.steps.find((st) => st.id === s.stepId);
            return step?.lessonId === where.step.lessonId;
          }
          return true;
        }),
      ),
      count: vi.fn(async ({ where }: any) =>
        state.attemptSteps.filter((s) => {
          if (where.attemptId != null && s.attemptId !== where.attemptId) return false;
          if (typeof where.isCorrect === "boolean" && s.isCorrect !== where.isCorrect) return false;
          if (where.step?.type?.not != null) {
            const step = state.steps.find((st) => st.id === s.stepId);
            if (step?.type === where.step.type.not) return false;
          }
          return true;
        }).length,
      ),
      findUnique: vi.fn(async ({ where }: any) =>
        state.attemptSteps.find(
          (s) => s.attemptId === where.attemptId_stepId.attemptId && s.stepId === where.attemptId_stepId.stepId,
        ) ?? null,
      ),
      create: vi.fn(async ({ data }: any) => {
        const row = {
          ...data,
          submittedAt: new Date(),
        };
        state.attemptSteps.push(row);
        return row;
      }),
      update: vi.fn(async ({ where, data }: any) => {
        const idx = state.attemptSteps.findIndex(
          (s) => s.attemptId === where.attemptId_stepId.attemptId && s.stepId === where.attemptId_stepId.stepId,
        );
        if (idx === -1) return null;
        state.attemptSteps[idx] = { ...state.attemptSteps[idx], ...data };
        return state.attemptSteps[idx];
      }),
    },
    $transaction: vi.fn(async (fn: (tx: typeof prismaMock) => Promise<unknown>) => {
      return fn(prismaMock);
    }),
  };

  return { state, prismaMock };
});

