    userHandCount: { findMany: () => Promise.resolve([]), update: () => Promise.resolve({}) },
    awardGrantEvent: { create: () => Promise.resolve({}) },
    $executeRawUnsafe: () => Promise.resolve(0),
  };
  return {
    getPrisma: () => ({
      user: { findUnique: () => Promise.resolve(null), findMany: () => Promise.resolve([]) },
