    s.minBuyInCents = 1000;
    s.maxBuyInCents = 10000;

    const d = new Dealer(s);
    await d.addPlayer("p1", "A", 5000);
    await d.addPlayer("p2", "B", 5000);

    expect(s.handId).toMatch(/^hand_/);
    expect(s.street).not.toBe("WAITING");

    await d.addBot("bot_2", "Bot", 5000);
    const botAfterAdd = s.playersById.get("bot_2");
    expect(botAfterAdd?.status).toBe("ABANDONED");
    expect(botAfterAdd?.sittingOutUntilNextHand).toBe(true);

    await expect((d as any).startHand()).resolves.toBeUndefined();
    const botOnNextHand = s.playersById.get("bot_2");
    expect(botOnNextHand?.status).toBe("ACTIVE");
    expect(botOnNextHand?.sittingOutUntilNextHand).toBe(false);
    expect((d as any).holeCardsByPlayerId.has("bot_2")).toBe(true);
  }, 15000);
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { Dealer } from "../../engine/Dealer.js";
import { PokerState } from "../../state/PokerState.js";
import { CashierService } from "../../engine/economy/CashierService.js";

type Tx = {
  playerId: string;
  handId?: string;
  kind: string;
  deltaCents: number;
};

class MemoryPersistence {
  enabled = true;
  handHistory = null;
  ledger = null;
  txs: Tx[] = [];
  balances = new Map<string, number>();

  async applyBankrollEvent(params: {
    playerId: string;
    handId?: string;
    kind: string;
    deltaCents: number;
  }) {
    const cur = this.balances.get(params.playerId) ?? 0;
    const next = cur + params.deltaCents;
    if (next < 0) throw new Error(`INSUFFICIENT_BALANCE:${params.playerId}`);
    this.balances.set(params.playerId, next);
    this.txs.push(params);
    return next;
  }

  async debitPlayer(params: {
    playerId: string;
    handId?: string;
    kind: string;
    amountCents: number;
  }) {
    return await this.applyBankrollEvent({
      playerId: params.playerId,
      handId: params.handId,
      kind: params.kind,
      deltaCents: -Math.abs(params.amountCents),
    });
  }

  async creditPlayer(params: {
    playerId: string;
    handId?: string;
    kind: string;
    amountCents: number;
  }) {
    return await this.applyBankrollEvent({
      playerId: params.playerId,
      handId: params.handId,
      kind: params.kind,
      deltaCents: Math.abs(params.amountCents),
    });
  }

  async assertHandBalanced(handId: string) {
    const delta = this.txs
      .filter((tx) => tx.handId === handId)
      .reduce((sum, tx) => sum + tx.deltaCents, 0);
    if (delta !== 0) throw new Error(`LEDGER_MISMATCH:${handId}:${delta}`);
  }

  private ensureBalance(playerId: string, currentBalance: number) {
    if (!this.balances.has(playerId)) {
      this.balances.set(playerId, currentBalance);
    }
  }

  async postBlind(params: {
    userId: string;
    handId?: string;
    amountCents: number;
    currentBalance: number;
    action: "POST_SB" | "POST_BB";
  }) {
    this.ensureBalance(params.userId, params.currentBalance);
    const next = await this.debitPlayer({
      playerId: params.userId,
      handId: params.handId,
      kind: params.action,
      amountCents: params.amountCents,
    });
    return next;
  }

  async debitBet(params: {
    userId: string;
    handId?: string;
    amountCents: number;
    action: "BET" | "RAISE" | "CALL" | "ALL_IN";
    currentBalance: number;
  }) {
    this.ensureBalance(params.userId, params.currentBalance);
    const next = await this.debitPlayer({
      playerId: params.userId,
      handId: params.handId,
      kind: params.action,
      amountCents: params.amountCents,
    });
    return next;
  }

  async creditPayout(params: {
    userId: string;
    handId?: string;
    amountCents: number;
    currentBalance: number;
  }) {
    this.ensureBalance(params.userId, params.currentBalance);
    const next = await this.creditPlayer({
      playerId: params.userId,
      handId: params.handId,
      kind: "PAYOUT",
      amountCents: params.amountCents,
    });
    return next;
  }
}

